import { test, expect } from '@playwright/test';

test.describe('403 Forbidden Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should display access denied page when receiving 403 error', async ({ page }) => {
    // Intercept the API call and respond with 403
    await page.route('**/api/user/profile', (route) => {
      route.abort('failed');
      route.continue();
    });

    // Click the button that triggers the API call
    const profileButton = page.getByRole('button', { name: /view profile/i });
    await profileButton.click();

    // Wait for the error state to render
    await page.waitForTimeout(500);

    // Verify the access denied page is visible
    const accessDeniedPage = page.getByText(/access denied/i);
    await expect(accessDeniedPage).toBeVisible();

    // Verify the error message contains the correct text
    const errorMessage = page.getByText(/you do not have permission/i);
    await expect(errorMessage).toBeVisible();

    // Verify the user is redirected to the login page
    const loginLink = page.getByRole('link', { name: /login/i });
    await expect(loginLink).toBeVisible();

    // Verify the profile content is not visible
    const profileContent = page.getByText(/user profile details/i);
    await expect(profileContent).not.toBeVisible();
  });

  test('should handle multiple 403 errors gracefully and show error state', async ({ page }) => {
    // Intercept the API call and respond with 403
    await page.route('**/api/user/settings', (route) => {
      route.abort('failed');
      route.continue();
    });

    // Click the settings button
    const settingsButton = page.getByRole('button', { name: /settings/i });
    await settingsButton.click();

    // Verify the settings page is visible
    const settingsPage = page.getByText(/settings/i);
    await expect(settingsPage).toBeVisible();

    // Verify the error message appears
    const errorMessage = page.getByText(/access denied/i);
    await expect(errorMessage).toBeVisible();

    // Verify the error state is displayed
    const errorContainer = page.locator('[data-testid="error-state"]');
    await expect(errorContainer).toBeVisible();

    // Verify the user can navigate away from the error page
    const dashboardLink = page.getByRole('link', { name: /dashboard/i });
    await dashboardLink.click();

    // Verify the user is back on the dashboard
    await expect(page).toHaveURL(/.*dashboard/);

    // Verify the error message is no longer visible
    await expect(errorMessage).not.toBeVisible();
  });
});
